import React, { useState, useEffect } from 'react';
import DepartmentCard from './components/DepartmentCard';
import ScheduleCalendar from './components/ScheduleCalendar';
import { PlusCircle, LayoutDashboard, Calendar as CalendarIcon, Database, ShieldCheck, Printer } from 'lucide-react';

function App() {
  // 1. STATE: Department Management
  const [departments, setDepartments] = useState([
    { id: 1, name: "College of Computer Studies", code: "CCS" },
    { id: 2, name: "Business Administration", code: "CBA" }
  ]);

  // 2. STATE: Global Master Schedule (Persistent across all generations)
  const [globalSchedule, setGlobalSchedule] = useState([]);
  const [allExamDates, setAllExamDates] = useState([]);

  // 3. LOGIC: Add Department Wrapper
  const addDepartment = () => {
    const name = prompt("Enter Department Name:");
    const code = prompt("Enter Department Code (e.g., PSYCH):");
    if (name && code) {
      setDepartments([...departments, { id: Date.now(), name, code: code.toUpperCase() }]);
    }
  };

  // 4. LOGIC: Unified Generation Handler
  // This merges new data into the global pool for conflict detection
  const handleScheduleGenerated = (newAssignments, newDates, deptCode) => {
    // A: Append new assignments to global list
    setGlobalSchedule(prev => {
      // Filter out any previous assignments for this specific department to avoid duplicates on re-generation
      const otherDepts = prev.filter(item => item.dept_code !== deptCode);

      // Add dept_code to each new assignment for the Calendar's UI
      const taggedAssignments = newAssignments.map(assign => ({
        ...assign,
        dept_code: deptCode
      }));

      return [...otherDepts, ...taggedAssignments];
    });

    // B: Merge and sort unique dates
    setAllExamDates(prev => {
      const combined = [...new Set([...prev, ...newDates])];
      return combined.sort((a, b) => new Date(a) - new Date(b));
    });
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-24 font-sans text-slate-900">

      {/* --- NAVIGATION BAR --- */}
      <nav className="bg-slate-900 px-8 py-5 mb-10 flex justify-between items-center sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-3">
          <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-500/20">
            <LayoutDashboard size={24} className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-black text-white tracking-tighter leading-none">EXAM_FLOW <span className="text-blue-500 text-xs font-bold ml-1 uppercase">PRO v2.0</span></h1>
            <p className="text-[9px] text-slate-400 font-black tracking-[0.3em] uppercase mt-1">Unified Conflict Resolver</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
            <div className="hidden md:flex items-center gap-2 bg-slate-800 px-4 py-2 rounded-xl border border-slate-700 mr-4">
                <ShieldCheck size={16} className="text-emerald-500"/>
                <span className="text-[10px] font-black text-slate-300 uppercase">System Secure</span>
            </div>
            <button 
              onClick={addDepartment}
              className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest flex items-center gap-2 transition-all active:scale-95 shadow-xl shadow-blue-600/20"
            >
              <PlusCircle size={18} /> Add Dept
            </button>
        </div>
      </nav>

      {/* --- MAIN CONTENT --- */}
      <main className="container mx-auto px-6 max-w-7xl">

        {/* HEADER STATS */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Total Exam Blocks</p>
                <p className="text-3xl font-black text-slate-800">{globalSchedule.length}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Managed Depts</p>
                <p className="text-3xl font-black text-slate-800">{departments.length}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Resource Status</p>
                <p className="text-3xl font-black text-emerald-600">OPTIMAL</p>
            </div>
        </div>

        {/* 1. INPUT ZONE: DEPARTMENT CARDS */}
        <div className="space-y-10 mb-20">
          <div className="flex items-center gap-3 mb-2">
            <Database className="text-slate-400" size={20}/>
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.4em]">Resource Management Layer</h3>
          </div>
          {departments.map((dept) => (
            <DepartmentCard 
              key={dept.id} 
              deptId={dept.id}
              deptName={dept.name} 
              deptCode={dept.code}
              onGenerate={(schedule, dates) => handleScheduleGenerated(schedule, dates, dept.code)}
            />
          ))}
        </div>

        {/* 2. OUTPUT ZONE: MASTER CALENDAR PREVIEW */}
        <div className="pt-10 border-t border-slate-200">
            {globalSchedule.length > 0 ? (
            <div className="animate-in fade-in slide-in-from-bottom-10 duration-1000">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-8 gap-4">
                <div>
                    <div className="flex items-center gap-2 mb-3">
                        <span className="bg-emerald-600 text-white text-[9px] font-black px-2 py-1 rounded-md uppercase tracking-widest">Global Live</span>
                        <span className="bg-slate-200 text-slate-600 text-[9px] font-black px-2 py-1 rounded-md uppercase tracking-widest">Conflict-Checked</span>
                    </div>
                    <h2 className="text-5xl font-black text-slate-900 tracking-tighter">
                    Master Scheduling <span className="text-blue-600">Timeline</span>
                    </h2>
                    <p className="text-slate-500 font-bold text-sm mt-2">Aggregated View of All Departmental Resource Allocations</p>
                </div>

                <button 
                    onClick={() => window.print()}
                    className="bg-white border-2 border-slate-200 px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-sm hover:border-blue-600 hover:text-blue-600 transition-all flex items-center gap-3 group"
                >
                    <Printer size={18} className="group-hover:animate-bounce"/> Export PDF Final Report
                </button>
                </div>

                <ScheduleCalendar 
                    scheduleData={globalSchedule} 
                    examDates={allExamDates} 
                />
            </div>
            ) : (
            <div className="text-center py-32 bg-white rounded-[40px] border-4 border-dashed border-slate-200">
                <div className="bg-slate-50 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6">
                    <CalendarIcon className="text-slate-300" size={40} />
                </div>
                <h3 className="text-xl font-black text-slate-800 tracking-tight mb-2">Awaiting Schedule Generation</h3>
